// Posts to publish: new only, with the caption and image each network needs.
const HASHTAGS = {
  'windows-mac': '#windows11 #mactips #pcfix #techtips',
  'phones': '#android #iphone #phonetips #mobilefix',
  'excel-office': '#excel #exceltips #spreadsheets #msoffice',
  'ai-tools': '#aitools #chatgpt #aiwriting #productivity',
  'websites-hosting': '#webhosting #dns #domains #webdev',
  'automation': '#n8n #automation #nocode #workflow',
};
const MAX_AGE_HOURS = 48;
const out = [];

for (const item of $input.all()) {
  const j = item.json;
  const link = j.link;
  if (!link) continue;

  // The RSS trigger should only hand us new items. This is the second guard:
  // on a re-activation it can replay the feed, and a replay would re-post.
  const published = new Date(j.isoDate || j.pubDate || 0).getTime();
  if (!published || Date.now() - published > MAX_AGE_HOURS * 3600 * 1000) continue;

  const slug = link.replace(/\/+$/, '').split('/').pop();
  const cats = [].concat(j.categories || []).map((c) => (typeof c === 'string' ? c : c && c.name) || '');
  const pillar = cats.find((c) => HASHTAGS[c]) || '';
  const answer = String(j['content:encoded'] || j.content || j.contentSnippet || j.description || '').trim();

  out.push({
    json: {
      title: j.title,
      link,
      slug,
      pillar,
      answer,
      // JPEG, not PNG: Instagram's container rejects PNG without saying so.
      ogImage: `https://a2zskillsewa.com/og/${slug}.jpg`,
      fbMessage: `${j.title}\n\n${answer}\n\nRead it: ${link}`,
      igCaption: `${j.title}\n\n${answer}\n\nFull guide on a2zskillsewa.com, link in bio.\n\n${HASHTAGS[pillar] || '#tech #howto'}`,
    },
  });
}

return out;

// The safety net.
//
// The model only ever sees this post's own title, short answer, pillar and
// tags, so anything it writes that cannot be traced back to those is an
// invention. Numbers and proper nouns are where that shows up, and on a site
// whose whole claim is tested facts, an invented version number is the one
// mistake that cannot be shrugged off.
//
// A rejected draft does not block the post. The deterministic copy built from
// the post's own fields goes out instead, and the run reports what was
// refused, because silence would make this look like it was working.
const src = $('Only genuinely new posts').item.json;
const haystack = [src.title, src.answer, src.pillar, src.slug.replace(/-/g, ' ')]
  .join(' ')
  .toLowerCase();

const ALLOW = new Set([
  'a2z', 'skills', 'a2zskillsewa', 'com', 'full', 'guide', 'link', 'bio', 'read',
  'the', 'this', 'that', 'your', 'you', 'and', 'but', 'for', 'with', 'what',
  'why', 'how', 'when', 'if', 'it', 'a', 'an', 'is', 'are', 'was', 'not', 'no',
  'on', 'in', 'to', 'of', 'most', 'every', 'both', 'here', 'there', 'they',
]);

const offenders = (text) => {
  const t = String(text || '').replace(/#\w+/g, ' ');
  const bad = [];
  for (const m of t.matchAll(/\b\d[\d.,]*\b/g)) {
    if (!haystack.includes(m[0].toLowerCase())) bad.push(m[0]);
  }
  for (const m of t.matchAll(/https?:\/\/[^\s)]+/g)) {
    if (!m[0].startsWith('https://a2zskillsewa.com')) bad.push(m[0]);
  }
  for (const m of t.matchAll(/\b[A-Z][A-Za-z0-9+.#]{2,}\b/g)) {
    const w = m[0].toLowerCase();
    if (!haystack.includes(w) && !ALLOW.has(w)) bad.push(m[0]);
  }
  return [...new Set(bad)];
};

let draft = {};
try {
  const raw = $('Write the social copy').item.json.body.choices[0].message.content;
  draft = JSON.parse(raw.replace(/^```json\s*|\s*```$/g, '').trim());
} catch (e) {
  draft = {};
}

const problems = [];
const fb = String(draft.facebook || '').trim();
const ig = String(draft.instagram || '').trim();

const fbBad = offenders(fb);
const igBad = offenders(ig);
if (!fb) problems.push('Facebook: the model returned nothing usable.');
else if (fbBad.length) problems.push(`Facebook: not in the post: ${fbBad.join(', ')}`);
if (!ig) problems.push('Instagram: the model returned nothing usable.');
else if (igBad.length) problems.push(`Instagram: not in the post: ${igBad.join(', ')}`);

const useModel = problems.length === 0;
const tags = src.igCaption.split('\n').pop();

return [
  {
    json: {
      ...src,
      fbMessage: useModel ? `${fb}\n\n${src.link}` : src.fbMessage,
      igCaption: useModel ? `${ig}\n\n${tags}` : src.igCaption,
      copySource: useModel ? 'model' : 'template',
      copyProblems: problems,
    },
  },
];

// Assert on the outcome, not on the run. A green execution that posted nothing
// is the failure this workflow exists to avoid.
const src = $('Refuse anything it invented').item.json;
const problems = [];

// A refused draft is not a failed run, but it must never pass unmentioned:
// silence is how you end up trusting copy nobody checked.
if (src.copySource === 'template') {
  problems.push(
    `Copy: the model's draft was refused and the template was posted instead.\n  ${src.copyProblems.join('\n  ')}`,
  );
}

const read = (nodeName) => {
  try {
    const j = $(nodeName).item.json;
    return (j && j.body) || j || null;
  } catch (e) {
    return null;
  }
};

const fb = read('Post to the Facebook Page');
if (!fb || !fb.id) problems.push(`Facebook: ${JSON.stringify((fb && fb.error) || fb || 'no response')}`);

const ig = read('Publish to Instagram');
if (!ig || !ig.id) {
  const status = read('Check the container');
  problems.push(
    `Instagram: ${JSON.stringify((ig && ig.error) || ig || (status && status.status_code) || 'no response')}`,
  );
}

return [{ json: { title: src.title, link: src.link, problems, count: problems.length } }];

